import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataItem,
  WixDataQuerySpec,
  WixDataRemoveOptions,
} from './types'

/**
 * Options builder for remove operations.
 *
 * Use this builder to configure remove behavior such as hooks suppression,
 * and conditional removal.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataRemoveOptionsBuilder {
  /**
   * Sets whether to suppress remove hooks.
   *
   * When `true`, the remove operation runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataRemoveOptionsBuilder
  /**
   * Sets whether to include draft items when removing items.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataRemoveOptionsBuilder
  /**
   * Removes the item only when it matches the specified condition.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataRemoveOptionsBuilder
  /**
   * Builds the remove options object.
   */
  build(): WixDataRemoveOptions
}

class WixDataRemoveOptionsBuilderImpl implements WixDataRemoveOptionsBuilder {
  constructor(private readonly options: WixDataRemoveOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataRemoveOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataRemoveOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataRemoveOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataRemoveOptions {
    return { ...this.options }
  }

  private copy(options: WixDataRemoveOptions): WixDataRemoveOptionsBuilder {
    return new WixDataRemoveOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new remove options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a remove options builder"
 * import { items, Filter, RemoveOptionsBuilder } from '@wix/data'
 *
 * const options = RemoveOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const removedItem = await items.remove<MyItem>(
 *   'myCollection',
 *   'myItemId',
 *   options
 * )
 * ```
 */
export const RemoveOptionsBuilder: () => WixDataRemoveOptionsBuilder = () =>
  new WixDataRemoveOptionsBuilderImpl()
